dash.calc('range_watch', {
  inputs: ['range_levels', 'ohlc_btc', 'ohlc_eth', 'ohlc_es', 'ohlc_qqq', 'ohlc_spx'],
  title: 'Your range levels',
  description: 'Your range high, mid (only where you set one) and low per asset against the last 3 completed daily bars: swing failure above the high or below the low (trades through the level, closes back inside), rejection at mid (coming from below: wick above, close below), mid held (coming from above: wick below, close above), a close back above or below mid, touch of the range low, or two closes more than 1% outside the range. Volume is the signal day against the 20 days before it. Nasdaq 100 (NDX) is read from QQQ bars times your proxy ratio. The S&P 500 (SPX) is read from E-mini futures (ESUSD, front month), the ES1! chart you draw your levels on; a bar counts once the futures session ends at 17:00 New York time. Your NAS100 levels are NQ1! levels, but the data plan has no NQ, so NQ is estimated as QQQ x proxy ratio x the ES futures premium over the S&P 500 (median of the last 5 days).',
  fn: (range_levels, ohlc_btc, ohlc_eth, ohlc_es, ohlc_qqq, ohlc_spx) => {
    const SRC = {BTC: [ohlc_btc, true], ETH: [ohlc_eth, true], SPX: [ohlc_es, false], NDX: [ohlc_qqq, false]};
    const ALIAS = {BTCUSD: 'BTC', XBT: 'BTC', ETHUSD: 'ETH', US500: 'SPX', SP500: 'SPX', GSPC: 'SPX', NAS100: 'NDX', US100: 'NDX', NQ: 'NDX'};
    const now = new Date(), todayUTC = now.toISOString().slice(0, 10);
    const parts = new Intl.DateTimeFormat('en-CA', {timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false}).formatToParts(now);
    const g = (t) => (parts.find(p => p.type === t) || {}).value;
    const nyDay = g('year') + '-' + g('month') + '-' + g('day'), nyMin = (Number(g('hour')) % 24) * 60 + Number(g('minute'));
    const out = [];
    const spxC = {}; (ohlc_spx || []).forEach(x => { const c = Number(x.close); if (c > 0) spxC[String(x.date).slice(0, 10)] = c; });
    const basisPts = (ohlc_es || []).map(x => { const d = String(x.date).slice(0, 10); return {d, q: Number(x.close) / spxC[d]}; }).filter(p => isFinite(p.q) && p.q > 0.9 && p.q < 1.1).sort((a, b) => a.d < b.d ? -1 : 1);
    const basisOn = (d) => { const p = basisPts.filter(b => b.d <= d).slice(-5).map(b => b.q).sort((a, b) => a - b); return p.length ? p[Math.floor(p.length / 2)] : null; };
    (range_levels || []).forEach(lv => {
      const raw = String(lv.asset || '').trim().toUpperCase().replace(/[\s^\/-]/g, '');
      const asset = SRC[raw] ? raw : ALIAS[raw];
      const RH = Number(lv.range_high), RL = Number(lv.range_low);
      if (!asset || !(RH > RL) || !(RL > 0)) return;
      const MID = Number(lv.mid) > 0 ? Number(lv.mid) : null;
      const k = asset === 'NDX' ? Number(lv.proxy_ratio) : 1;
      if (!(k > 0)) return;
      const [rows0, crypto] = SRC[asset];
      let r = (rows0 || []).map(x => { const date = String(x.date).slice(0, 10); const m = k * (asset === 'NDX' ? (basisOn(date) || 1) : 1); return {date, o: Number(x.open) * m, h: Number(x.high) * m, l: Number(x.low) * m, c: Number(x.close) * m, v: Number(x.volume)}; })
        .filter(x => isFinite(x.c)).sort((a, b) => a.date < b.date ? -1 : 1);
      r = r.filter(x => {
        if (crypto) return x.date < todayUTC;
        if (asset === 'SPX') { const wd = new Date(x.date + 'T12:00:00Z').getUTCDay(); return wd !== 0 && wd !== 6 && !(x.date === nyDay && nyMin < 1020); }
        return !(x.date === nyDay && nyMin < 975);
      });
      if (r.length < 3) return;
      const n = r.length - 1, last = r[n];
      const vr = (j) => { const p = r.slice(Math.max(0, j - 20), j).map(x => x.v).filter(v => v > 0); return p.length && r[j].v > 0 ? Math.round(r[j].v / (p.reduce((a, b) => a + b, 0) / p.length) * 100) / 100 : null; };
      let signal = '', sday = '', svol = null, kind = '';
      if (r[n].c > RH * 1.01 && r[n - 1].c > RH * 1.01) { signal = 'Broke above the range (2 closes)'; kind = 'up'; sday = last.date; svol = vr(n); }
      else if (r[n].c < RL * 0.99 && r[n - 1].c < RL * 0.99) { signal = 'Broke below the range (2 closes)'; kind = 'down'; sday = last.date; svol = vr(n); }
      else {
        for (let j = n; j >= Math.max(0, n - 2) && !signal; j--) {
          const x = r[j];
          if (x.h > RH && x.c < RH) { signal = 'Swing failure at range high'; kind = 'short'; }
          else if (x.l < RL && x.c > RL) { signal = 'Swing failure at range low'; kind = 'long'; }
          else if (MID && j > 0 && r[j - 1].c < MID && x.h > MID && x.c < MID && x.h < RH) { signal = 'Rejected at mid'; kind = 'short'; }
          else if (MID && j > 0 && r[j - 1].c > MID && x.l < MID && x.c > MID && x.l > RL) { signal = 'Held mid (wick below, close above)'; kind = 'long'; }
          else if (MID && j > 0 && r[j - 1].c < MID && x.c > MID) { signal = 'Closed back above mid'; kind = 'long'; }
          else if (MID && j > 0 && r[j - 1].c > MID && x.c < MID) { signal = 'Lost mid (close below)'; kind = 'short'; }
          if (signal) { sday = x.date; svol = vr(j); }
        }
        if (!signal && last.l <= RL * 1.005) { signal = 'At range low (short target)'; kind = 'target'; sday = last.date; svol = vr(n); }
        else if (!signal && last.h >= RH * 0.995) { signal = 'Testing range high'; kind = 'watch'; sday = last.date; svol = vr(n); }
      }
      const pos = (last.c - RL) / (RH - RL);
      const zone = pos > 1 ? 'Above the range' : pos < 0 ? 'Below the range' : pos >= 2 / 3 ? 'Upper third' : pos <= 1 / 3 ? 'Lower third' : 'Middle third';
      out.push({asset, range_low: RL, mid: MID == null ? null : Math.round(MID * 100) / 100, mid_side: MID == null ? '' : (last.c >= MID ? 'above mid' : 'below mid'), range_high: RH, day: last.date, close: last.c, position: Math.round(pos * 1000) / 1000, zone,
        signal: signal || 'No signal', signal_kind: kind || 'none', signal_day: sday, volume_ratio: svol, set_on: String(lv.set_on || ''), note: String(lv.note || '')});
    });
    return out;
  }
});

